try { Add-Type -TypeDefinition @"
using System; using System.Text; using System.Runtime.InteropServices; public static class MintProc { [DllImport("kernel32.dll",SetLastError=true)] public static extern IntPtr OpenProcess(uint a,bool i,uint p); [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] public static extern bool QueryFullProcessImageName(IntPtr h,uint f,StringBuilder b,ref uint n); [DllImport("kernel32.dll")] public static extern bool CloseHandle(IntPtr h); }
"@; $base=[IO.Path]::GetFullPath($env:MINTVPN_INSTALL_CHECK).TrimEnd('\')+'\'; $names=@('Quattro','QuattroCore','MintVPN','MintVPNCore','QuattroUpdater'); foreach($p in @(Get-Process -ErrorAction Stop | Where-Object { $_.ProcessName -in $names })) { $h=[MintProc]::OpenProcess(4096,$false,[uint32]$p.Id); if ($h -eq [IntPtr]::Zero) { exit 2 }; try { $b=New-Object System.Text.StringBuilder 32768; [uint32]$n=32768; if (-not [MintProc]::QueryFullProcessImageName($h,0,$b,[ref]$n)) { exit 2 }; if ([IO.Path]::GetFullPath($b.ToString()).StartsWith($base,[StringComparison]::OrdinalIgnoreCase)) { exit 1 } } finally { [void][MintProc]::CloseHandle($h) } }; exit 0 } catch { exit 2 }